fn solve(a: i8, b: i8) -> (i8, i8) {
    // We have the system:
    //   x + y = a
    //   x - y = b
    // Adding both equations: 2x = a + b  => x = (a + b) / 2
    // Subtracting    : 2y = a - b  => y = (a - b) / 2
    //
    // Since a and b are in [-100, 100], their sum and difference lie in [-200, 200],
    // so we cast to i16 to avoid overflow during the addition/subtraction,
    // then divide by 2, and cast back to i8 (the result will fit in i8).

    let x = ((a as i16 + b as i16) / 2) as i8;
    let y = ((a as i16 - b as i16) / 2) as i8;
    (x, y)
}

